INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: LED Terbakar atau Tidak Mau Menyala$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak pemula elektronik yang mencoba menyalakan LED langsung dari baterai atau adaptor, lalu kecewa: LED-nya redup, sangat panas, bahkan langsung mati begitu disambung. Sebaliknya ada juga yang sudah merangkai tetapi LED tidak menyala sama sekali. Kedua masalah ini hampir selalu berasal dari dua hal yang sama: tidak memakai resistor pembatas arus, atau kaki LED terpasang terbalik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: LED Adalah Dioda yang Memancarkan Cahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$LED (Light Emitting Diode) adalah komponen semikonduktor yang mengubah arus listrik menjadi cahaya. Seperti dioda biasa, LED hanya mengalirkan arus ke satu arah: dari kaki positif (anoda) ke kaki negatif (katoda). Kaki anoda biasanya lebih panjang, dan pada badan LED ada bagian datar di sisi katoda. Setiap LED memiliki tegangan maju sekitar 1,8 sampai 3,3 volt tergantung warnanya — merah dan kuning paling rendah, biru dan putih paling tinggi. Arus idealnya hanya sekitar 10 sampai 20 miliampere; lebih dari itu LED akan cepat panas dan rusak.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$LED 5 mm warna apa saja (1 buah untuk latihan pertama)$$, $$Resistor 220 sampai 470 ohm (wajib, sebagai pembatas arus)$$, $$Breadboard (papan percobaan tanpa solder)$$, $$Kabel jumper secukupnya$$, $$Sumber tegangan 5 volt (adaptor USB, baterai dengan regulator, atau output 5V Arduino)$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Merangkai LED dengan Benar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Hitung resistor: untuk LED merah (2 volt) pada sumber 5 volt, butuh (5-2) dibagi 0,02 = 150 ohm minimal; amannya pakai 220 ohm.$$, $$Tancapkan LED ke breadboard: kaki panjang (anoda) dan kaki pendek (katoda) di lajur yang berbeda.$$, $$Hubungkan satu kaki resistor ke kaki anoda LED, kaki resistor satunya ke jalur positif sumber tegangan.$$, $$Hubungkan kaki katoda LED ke jalur negatif (ground) sumber tegangan.$$, $$Nyalakan sumber tegangan: LED seharusnya menyala terang tetapi tidak panas.$$, $$Coba ganti resistor dengan nilai lebih besar (misalnya 1k ohm): cahaya meredup — inilah bukti resistor mengendalikan arus.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Menyambung LED langsung ke baterai tanpa resistor: LED terbakar dalam hitungan detik, bahkan bisa pecah.$$, $$Kaki terbalik (anoda ke negatif): LED tidak menyala; belum tentu langsung rusak, tetapi tegangan balik berlebih bisa merusaknya.$$, $$Resistor terlalu kecil: LED menyala sangat terang lalu cepat mati karena kepanasan.$$, $$Korsleting kaki LED dengan kabel jumper: sumber tegangan bisa rusak; selalu matikan daya saat mengubah rangkaian.$$, $$Peringatan keselamatan: jangan bereksperimen dengan listrik PLN 220 volt — latihan ini hanya untuk tegangan rendah, maksimal 12 volt.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Langkah Berikutnya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$LED menyala stabil, terang, dan tidak panas saat disentuh setelah 1 menit.$$, $$Kamu bisa mengenali kaki anoda dan katoda tanpa melihat gambar.$$, $$Kamu bisa menghitung resistor yang tepat untuk warna LED dan tegangan sumber yang berbeda.$$, $$Langkah berikutnya: rangkai 3 LED seri atau paralel, lalu kendalikan LED memakai tombol push-button atau output Arduino.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ayam Goreng Keras, Hambar, dan Lengkuasnya Gosong$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Ayam goreng lengkuas seharusnya gurih dengan taburan lengkuas parut yang renyah dan harum. Namun banyak yang gagal: ayamnya keras seperti karet, bumbu tidak meresap sampai ke dalam, dan parutan lengkuas malah gosong pahit saat digoreng. Masalahnya biasanya pada tiga hal: ayam tidak diungkep dulu, api terlalu besar, dan lengkuas digoreng bersamaan dengan ayam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Kunci Kelezatan Ada pada Ungkep dan Lengkuas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Ungkep adalah teknik merebus ayam dengan bumbu hingga air menyusut — inilah yang membuat bumbu meresap sampai ke tulang dan daging menjadi empuk. Lengkuas (laos) memberi aroma khas yang tidak bisa digantikan jahe atau kunyit. Rahasia taburan renyah: lengkuas diparut halus, diperas sedikit airnya, lalu digoreng terpisah dengan api sedang sampai keemasan. Digoreng bersama ayam justru membuatnya gosong karena ayam butuh waktu goreng lebih lama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Bahan-bahan (untuk 1 ekor ayam, 8 potong)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$1 ekor ayam (sekitar 800 gram sampai 1 kg), potong 8 bagian$$, $$150 gram lengkuas muda, kupas dan parut halus$$, $$8 siung bawang merah dan 5 siung bawang putih$$, $$3 butir kemiri sangrai, 1 sdt ketumbar, 1 sdt garam, setengah sdt gula$$, $$2 lembar daun salam dan 2 batang serai yang digeprek$$, $$500 ml air dan minyak goreng secukupnya$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Ungkep Lalu Goreng$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Haluskan bawang merah, bawang putih, kemiri, ketumbar, garam, dan gula. Campur dengan lengkuas parut, tetapi sisakan 3 sendok makan lengkuas parut untuk taburan.$$, $$Lumuri ayam dengan bumbu, tambahkan daun salam, serai, dan air. Diamkan 15 menit agar bumbu menempel.$$, $$Ungkep dengan api sedang-kecil selama 25 sampai 30 menit sampai air menyusut dan ayam empuk. Angkat ayam dan tiriskan.$$, $$Panaskan minyak dengan api sedang. Goreng ayam 3 sampai 4 menit per sisi sampai keemasan. Jangan terlalu lama agar tidak keras.$$, $$Goreng lengkuas parut yang disisihkan secara terpisah dengan api sedang, aduk terus sampai keemasan dan renyah, sekitar 5 menit. Tiriskan di atas tisu.$$, $$Sajikan ayam goreng dengan taburan lengkuas renyah di atasnya.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kesalahan yang Sering Terjadi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Menggoreng dengan api besar: luar gosong, dalam masih mentah atau alot.$$, $$Melewatkan proses ungkep: bumbu hanya menempel di luar, daging hambar.$$, $$Menggoreng lengkuas bersama ayam: lengkuas gosong dan pahit sebelum ayam matang.$$, $$Minyak kurang panas saat ayam masuk: ayam menyerap banyak minyak dan menjadi lembek berminyak.$$, $$Memakai lengkuas tua yang berserat kasar: taburan menjadi alot, bukan renyah.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Penyajian$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Daging empuk dan bumbu terasa sampai ke dalam, bukan hanya di permukaan.$$, $$Kulit keemasan dan tidak berminyak berlebih.$$, $$Taburan lengkuas renyah, harum, dan tidak pahit.$$, $$Sajikan hangat dengan nasi putih, lalapan, dan sambal. Sisa ayam ungkep yang belum digoreng bisa disimpan di kulkas 2 sampai 3 hari atau di freezer 2 minggu.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Logam yang Pernah Lebih Mahal daripada Emas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Pada pertengahan abad ke-19, aluminium adalah logam termahal di dunia — lebih mahal daripada emas dan perak. Kaisar Napoleon III dari Prancis dikabarkan memakai peralatan makan dari aluminium untuk jamuan kehormatan, sementara tamu biasa hanya mendapat peralatan emas. Penyebabnya sederhana: aluminium sangat sulit dimurnikan dari bijihnya. Semua berubah pada tahun 1886 ketika Charles Hall di Amerika dan Paul Heroult di Prancis menemukan cara elektrolisis yang murah dalam waktu yang hampir bersamaan. Harga aluminium jatuh, dan logam mewah itu menjadi bahan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Aluminium$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', ARRAY[$$Sangat ringan: massa jenis 2,7 gram per cm kubik, sekitar sepertiga massa jenis besi — alasan utama dipakai di pesawat terbang.$$, $$Tahan karat: permukaannya membentuk lapisan oksida tipis yang melindungi dari korosi lebih lanjut.$$, $$Penghantar listrik dan panas yang baik: kabel transmisi listrik banyak memakai aluminium.$$, $$Lunak dan mudah dibentuk: bisa digiling menjadi foil setipis 0,016 mm.$$, $$Tidak beracun dan tidak bereaksi dengan makanan: aman untuk kemasan dan peralatan masak.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dari Bauksit menjadi Aluminium$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Aluminium tidak ditemukan bebas di alam; ia diekstrak dari bijih bauksit. Prosesnya dua tahap: pertama, proses Bayer memurnikan bauksit menjadi alumina (aluminium oksida) dengan larutan natrium hidroksida panas. Kedua, proses Hall-Heroult melelehkan alumina dalam kriolit cair lalu mengalirkan arus listrik raksasa untuk memisahkan aluminium murni. Proses ini sangat boros listrik — memproduksi 1 kg aluminium butuh sekitar 13 sampai 15 kWh listrik. Inilah alasan pabrik aluminium selalu dibangun dekat sumber listrik murah seperti PLTA.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Aluminium di Sekitar Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Transportasi: bodi pesawat terbang, rangka sepeda, dan pelek mobil.$$, $$Kemasan: kaleng minuman, foil makanan, dan tutup botol.$$, $$Konstruksi: kusen jendela, atap, dan rangka bangunan ringan.$$, $$Rumah tangga: panci, wajan, dan peralatan dapur.$$, $$Listrik: kabel transmisi tegangan tinggi dan pendingin perangkat elektronik.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Daur Ulang: Keunggulan Tersembunyi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Keunggulan terbesar aluminium adalah ia bisa didaur ulang tanpa batas tanpa kehilangan kualitas. Mendaur ulang aluminium hanya butuh sekitar 5 persen energi dibandingkan memproduksi dari bijih baru — penghematan 95 persen. Kaleng minuman yang dibuang hari ini bisa kembali menjadi kaleng baru di rak toko dalam waktu sekitar 60 hari. Kebiasaan memilah sampah kaleng aluminium memberi nilai ekonomi sekaligus mengurangi beban lingkungan.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Perang Terpanjang dalam Sejarah Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Perang Aceh berlangsung dari tahun 1873 hingga 1904 — lebih dari 30 tahun, menjadikannya perang kolonial terpanjang dan termahal yang pernah dihadapi Belanda. Belanda mengerahkan ratusan ribu tentara dan menghabiskan biaya sangat besar, sementara rakyat Aceh bertahan dengan strategi gerilya, benteng pertahanan, dan semangat perlawanan yang tak padam meski ibu kota mereka jatuh. Perang ini menjadi simbol keteguhan perlawanan rakyat Nusantara terhadap penjajahan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang: Mengapa Belanda Menyerang Aceh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pada abad ke-19, Aceh adalah kesultanan berdaulat yang menguasai perdagangan lada dan memiliki hubungan diplomatik dengan negara-negara Eropa serta Kesultanan Utsmaniyah. Belanda yang ingin menguasai seluruh Nusantara merasa terancam oleh kedaulatan Aceh. Melalui Traktat Sumatera tahun 1871, Inggris memberi kebebasan kepada Belanda untuk memperluas kekuasaan ke Aceh. Belanda kemudian mencari alasan dan pada 26 Maret 1873 menyatakan perang terhadap Kesultanan Aceh.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jalannya Perang: Tiga Fase Perlawanan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Fase pertama (1873-1874): Belanda menyerang lewat laut dan berhasil merebut istana sultan di Kutaraja (kini Banda Aceh), tetapi Sultan Mahmudsyah wafat dan perlawanan justru meluas ke daerah-daerah. Fase kedua (1874-1890-an): Belanda menguasai kota-kota pesisir, namun rakyat Aceh bergerilya dari pedalaman dengan benteng-benteng pertahanan. Fase ketiga (1890-an-1904): di bawah Gubernur Jenderal Van Heutsz, Belanda memakai strategi keras dengan garis benteng konsentrasi dan operasi militer besar ke pedalaman. Satu per satu pemimpin gugur atau menyerah, hingga pada 1904 Belanda mengklaim perang selesai, meski perlawanan kecil masih berlanjut bertahun-tahun kemudian.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tokoh-tokoh Perlawanan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Teuku Umar: panglima cerdik yang berpura-pura bekerjasama dengan Belanda untuk merebut senjata, lalu berbalik melawan; gugur tahun 1899.$$, $$Cut Nyak Dhien: memimpin gerilya belasan tahun setelah suaminya Teuku Umar gugur; ditangkap tahun 1905 dan diasingkan ke Sumedang.$$, $$Cut Nyak Meutia: pejuang perempuan yang gugur dalam pertempuran tahun 1910.$$, $$Teuku Cik Di Tiro: ulama kharismatik yang mengobarkan semangat perlawanan di awal perang; wafat tahun 1891.$$, $$Panglima Polem: pemimpin yang akhirnya menyerah pada tahun 1903 setelah tekanan militer besar-besaran.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Akhir Perang dan Warisannya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Secara resmi Belanda menyatakan Aceh damai pada tahun 1904, tetapi perlawanan sporadis terus terjadi hingga tahun 1910-an. Perang Aceh menelan korban puluhan ribu jiwa di kedua belah pihak dan menjadi pelajaran mahal bagi Belanda. Bagi Indonesia, perang ini meninggalkan warisan berharga: bukti bahwa perlawanan rakyat yang terorganisir dan berakar pada keyakinan mampu bertahan puluhan tahun melawan kekuatan militer modern. Nama-nama pahlawan Aceh kini diabadikan sebagai pahlawan nasional, dan semangat pantang menyerah mereka menjadi bagian dari memori kolektif bangsa.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Menjelaskan pengertian laju reaksi dan cara menghitungnya.$$, $$Menyebutkan faktor-faktor yang memengaruhi laju reaksi beserta penjelasannya.$$, $$Menganalisis data percobaan sederhana terkait laju reaksi.$$, $$Menerapkan konsep laju reaksi dalam kehidupan sehari-hari.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Laju Reaksi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Laju reaksi adalah ukuran seberapa cepat reaktan (pereaksi) berubah menjadi produk (hasil reaksi) dalam satuan waktu. Secara matematis, laju reaksi dinyatakan sebagai perubahan konsentrasi per satuan waktu, misalnya mol per liter per detik (M/s). Contoh sederhana: tablet vitamin C larut lebih cepat dalam air panas daripada dalam air dingin — artinya laju pelarutan lebih besar pada suhu tinggi. Dalam kimia, laju reaksi dipelajari agar kita bisa mengendalikan kecepatan proses, misalnya mempercepat produksi di pabrik atau memperlambat pembusukan makanan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Faktor-faktor yang Memengaruhi Laju Reaksi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Konsentrasi: semakin pekat reaktan, semakin sering partikel bertumbukan, semakin cepat reaksi. Contoh: kayu terbakar lebih cepat dalam oksigen murni daripada di udara biasa.$$, $$Suhu: setiap kenaikan 10 derajat Celsius, laju reaksi umumnya naik 2 sampai 3 kali lipat karena energi kinetik partikel bertambah.$$, $$Luas permukaan: serbuk kayu terbakar jauh lebih cepat daripada balok kayu karena bidang sentuhnya dengan oksigen lebih luas.$$, $$Katalis: zat yang mempercepat reaksi tanpa ikut bereaksi, dengan cara menurunkan energi aktivasi. Contoh: enzim dalam tubuh dan katalis pada knalpot mobil.$$, $$Tekanan (untuk gas): menaikkan tekanan gas sama artinya dengan menaikkan konsentrasi — tumbukan makin sering, reaksi makin cepat.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Soal Terpecahkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'EXAMPLE', 7, jsonb_build_object('text', $$Diketahui reaksi A menjadi B. Konsentrasi A mula-mula 0,8 M, setelah 40 detik tersisa 0,4 M. Hitung laju reaksi rata-rata! Penyelesaian: laju = perubahan konsentrasi dibagi waktu = (0,8 - 0,4) M / 40 s = 0,4 / 40 = 0,01 M/s. Jadi laju reaksi rata-ratanya 0,01 mol per liter per detik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Sebutkan 5 faktor yang memengaruhi laju reaksi beserta satu contohnya masing-masing!$$, $$Mengapa makanan lebih awet disimpan di kulkas daripada di suhu ruang? Jelaskan dengan konsep laju reaksi!$$, $$Dalam suatu percobaan, konsentrasi reaktan turun dari 1,0 M menjadi 0,6 M dalam 20 detik. Hitung laju reaksi rata-ratanya!$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Konsentrasi, suhu, luas permukaan, katalis, tekanan — masing-masing dengan contoh yang tepat (lihat materi di atas).$$, $$Suhu rendah memperlambat gerak partikel sehingga tumbukan efektif berkurang; laju reaksi pembusukan oleh bakteri dan enzim menurun, makanan lebih awet.$$, $$Laju = (1,0 - 0,6) M / 20 s = 0,4 / 20 = 0,02 M/s.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Menjelaskan pengertian puasa dalam Islam dengan bahasa sendiri.$$, $$Menyebutkan rukun dan syarat wajib puasa.$$, $$Menyebutkan hal-hal yang membatalkan puasa.$$, $$Menjelaskan hikmah berpuasa dalam kehidupan sehari-hari.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Puasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Puasa (shaum) artinya menahan diri. Dalam Islam, puasa adalah menahan diri dari makan, minum, dan segala hal yang membatalkan puasa, mulai dari terbit fajar hingga terbenam matahari, dengan niat karena Allah. Puasa Ramadhan wajib bagi setiap muslim yang sudah baligh dan berakal. Allah berfirman dalam Al-Quran surat Al-Baqarah ayat 183 bahwa puasa diwajibkan agar kita menjadi orang yang bertakwa. Selain Ramadhan, ada juga puasa sunnah seperti puasa Senin dan Kamis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Rukun dan Syarat Puasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Rukun puasa ada dua: niat, dan menahan diri dari hal yang membatalkan dari fajar hingga maghrib.$$, $$Syarat wajib puasa: beragama Islam, baligh, berakal, dan mampu melaksanakannya.$$, $$Syarat sah puasa: beragama Islam, berakal, suci dari haid dan nifas bagi perempuan, serta dilakukan pada waktu yang diperbolehkan.$$, $$Niat puasa Ramadhan dilakukan pada malam hari sebelum fajar, contohnya: Aku niat berpuasa esok hari untuk menunaikan fardhu bulan Ramadhan karena Allah.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Hal-hal yang Membatalkan Puasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Makan dan minum dengan sengaja.$$, $$Muntah dengan sengaja.$$, $$Keluar darah haid atau nifas.$$, $$Hilang akal atau pingsan seharian penuh.$$, $$Keluar dari agama Islam (murtad).$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Hikmah Berpuasa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Melatih kesabaran dan pengendalian diri.$$, $$Menumbuhkan rasa syukur atas nikmat Allah.$$, $$Melatih kepedulian kepada orang yang kurang mampu dengan merasakan lapar seperti mereka.$$, $$Menjaga kesehatan tubuh karena pola makan menjadi lebih teratur.$$, $$Mendapat pahala besar dan ampunan dosa dari Allah.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Apa pengertian puasa menurut istilah? Kunci: menahan diri dari makan, minum, dan hal yang membatalkan dari terbit fajar hingga terbenam matahari dengan niat karena Allah.$$, $$Sebutkan dua rukun puasa! Kunci: niat dan menahan diri dari hal yang membatalkan.$$, $$Sebutkan tiga hal yang membatalkan puasa! Kunci: makan atau minum dengan sengaja, muntah dengan sengaja, keluar darah haid atau nifas.$$]::text[]));
